    "translation": [
      "Tanaka seharusnya sudah tiba di stasiun. Toko ini seharusnya buka juga hari Minggu. Kalau lelah, sebaiknya tidur lebih awal.",
      "Kalau demam, sebaiknya tidak pergi ke kantor. Kuncinya seharusnya ada di dalam tas.",
      "Penulis menjelaskan rencana untuk kegiatan berikutnya. Penulis menjelaskan kebiasaan yang sengaja dipertahankan. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai.",
      "Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan."
    ],
