    "translation": [
      "Saya memutuskan belajar di rumah akhir pekan ini. Saya memutuskan untuk melanjutkan pekerjaan ini. Saya membiasakan makan sayur setiap pagi.",
      "Tolong usahakan agar tidak terlambat. Saya berusaha membiasakan berbicara bahasa Jepang setiap hari. Saya berusaha tidak minum kopi pada malam hari.",
      "Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa.",
      "Memilih cara yang sesuai dengan situasi saat itu juga diperlukan. Sambil mempertimbangkan alasannya, penulis membandingkan cara mana yang paling baik. Karena berbagi informasi dengan orang sekitar, penyebab masalah menjadi lebih mudah dipahami. Akhir-akhir ini penulis membiasakan diri memeriksa bukan hanya jadwal, tetapi juga alasannya. Penulis merasa sebaiknya mendengarkan pendapat orang sekitar ketika diperlukan. Pada pagi hari waktu pelajaran diperiksa.",
      "Di kelas, siswa membaca bahasa Jepang dan mendengarkan penjelasan guru. Kosakata yang belum dipahami ditulis di buku catatan. Saat istirahat, siswa membicarakan isi pelajaran bersama teman. Setelah pulang, isi pelajaran hari itu diperiksa sekali lagi. Ada rencana belajar berikutnya yang akan dilakukan. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya."
    ],
