    "translation": [
      "Diputuskan bahwa bulan depan saya pindah tugas ke Osaka. Sudah diputuskan bahwa tahun depan saya akan pergi ke Jepang. Tolong usahakan agar tidak terlambat. Saya berusaha membiasakan berbicara bahasa Jepang setiap hari.",
      "Saya berusaha tidak minum kopi pada malam hari. Saya mencatat agar tidak lupa. Saya membiasakan makan sayur setiap pagi.",
      "Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan. Sambil mempertimbangkan alasannya, penulis membandingkan cara mana yang paling baik. Karena berbagi informasi dengan orang sekitar, penyebab masalah menjadi lebih mudah dipahami. Akhir-akhir ini penulis membiasakan diri memeriksa bukan hanya jadwal, tetapi juga alasannya. Penulis merasa sebaiknya mendengarkan pendapat orang sekitar ketika diperlukan. Pada pagi hari, jadwal hari itu diperiksa di kantor.",
      "Pada pagi hari, dokumen diperiksa dan pekerjaan yang diperlukan dilanjutkan. Hal yang belum dipahami ditanyakan kepada senior atau rekan kerja. Pada sore hari, jadwal hari berikutnya juga diperiksa. Hal penting dicatat. Ada rencana pekerjaan berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan.",
      "Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Penulis menjelaskan alasan dan tindakan dengan hubungan sebab-akibat."
    ],
