    "translation": [
      "Menurut ramalan cuaca, katanya besok akan hujan. Katanya perusahaan itu juga tidak libur hari Minggu. Tanaka mengatakan bahwa besok dia akan datang. Yamada mengatakan hari ini dia akan libur/tidak masuk.",
      "Ada rencana untuk hari berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya.",
      "Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Penulis menjelaskan alasan dan tindakan dengan hubungan sebab-akibat. Penulis menjelaskan rencana untuk kegiatan berikutnya.",
      "Penulis menjelaskan kebiasaan yang sengaja dipertahankan. Menurut 鈴木, kabarnya akhir-akhir ini semakin banyak orang yang menggunakan cara ini. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan."
    ],
