    "translation": [
      "Kue ini kelihatannya enak. Kelihatannya akan turun hujan. Katanya masakan toko ini enak. Katanya Tanaka akan menikah bulan depan.",
      "Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Penulis menjelaskan alasan dan tindakan dengan hubungan sebab-akibat. Penulis menjelaskan rencana untuk kegiatan berikutnya.",
      "Penulis menjelaskan kebiasaan yang sengaja dipertahankan. Menurut ミラー, kabarnya akhir-akhir ini semakin banyak orang yang menggunakan cara ini. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai.",
      "Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa."
    ],
