    "translation": [
      "Tanaka mengatakan bahwa besok dia akan datang. Yamada mengatakan hari ini dia akan libur/tidak masuk. Katanya Tanaka akan menikah bulan depan.",
      "Katanya guru baru sangat baik hati. Tanaka kelihatannya sehat/bersemangat. Sepertinya Tanaka sibuk.",
      "Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan.",
      "Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan. Sambil mempertimbangkan alasannya, penulis membandingkan cara mana yang paling baik. Karena berbagi informasi dengan orang sekitar, penyebab masalah menjadi lebih mudah dipahami. Akhir-akhir ini penulis membiasakan diri memeriksa bukan hanya jadwal, tetapi juga alasannya. Penulis merasa sebaiknya mendengarkan pendapat orang sekitar ketika diperlukan.",
      "Pada pagi hari, jadwal hari itu diperiksa terlebih dahulu. Kegiatan pagi dan sore sedikit berbeda. Waktu penting ditulis dalam catatan. Pada hari dengan banyak rencana, urutannya ditentukan. Pada akhirnya, jadwal hari berikutnya juga diperiksa."
    ],
