    "translation": [
      "'Dilarang masuk' berarti tidak boleh masuk. Tanda ini berarti dilarang merokok. Katanya perusahaan itu juga tidak libur hari Minggu. Menurut ramalan cuaca, katanya besok akan hujan.",
      "'Gratis' berarti tidak membutuhkan uang. 'Jokō' berarti berkendara pelan. Apa arti kata ini?",
      "Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan. Sambil mempertimbangkan alasannya, penulis membandingkan cara mana yang paling baik. Karena berbagi informasi dengan orang sekitar, penyebab masalah menjadi lebih mudah dipahami. Akhir-akhir ini penulis membiasakan diri memeriksa bukan hanya jadwal, tetapi juga alasannya. Penulis merasa sebaiknya mendengarkan pendapat orang sekitar ketika diperlukan.",
      "Pada pagi hari, ramalan cuaca diperiksa. Pada hari hujan, payung dibawa saat keluar. Pada hari berangin kencang, rencana sedikit diubah. Cuaca sore diperiksa sebelum berangkat. Tempat yang akan didatangi ditentukan berdasarkan cuaca. Ada rencana untuk hari berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya.",
      "Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal."
    ],
