    "translation": [
      "Walaupun sekalipun hujan, saya akan pergi. Walaupun tidak ada banyak waktu, saya belajar sedikit setiap hari. Jika hujan, pertandingan dibatalkan.",
      "Jika tidak mengerti, tolong tanyakan kepada guru. Walaupun sulit, saya akan melakukannya sampai akhir.",
      "Penulis menjelaskan rencana untuk kegiatan berikutnya. Penulis menjelaskan kebiasaan yang sengaja dipertahankan. Menurut 山田, kabarnya akhir-akhir ini semakin banyak orang yang menggunakan cara ini. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu.",
      "Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan."
    ],
