    "translation": [
      "Dalam keadaan darurat, tolong telepon nomor ini. Jika paspor hilang, silakan pergi ke polisi. Padahal sudah minum obat, saya masih demam.",
      "Meskipun kota ini tenang, depan stasiun ramai. Jika hujan, pertandingan dibatalkan. Jika akan terlambat, tolong hubungi.",
      "Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali.",
      "Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan. Sambil mempertimbangkan alasannya, penulis membandingkan cara mana yang paling baik.",
      "Karena berbagi informasi dengan orang sekitar, penyebab masalah menjadi lebih mudah dipahami. Akhir-akhir ini penulis membiasakan diri memeriksa bukan hanya jadwal, tetapi juga alasannya. Penulis merasa sebaiknya mendengarkan pendapat orang sekitar ketika diperlukan. Waktu keberangkatan dan jadwal kereta diperiksa. Di stasiun, peta dan petunjuk dilihat."
    ],
