    "translation": [
      "Meskipun kota ini tenang, depan stasiun ramai. Padahal sudah banyak belajar, saya tidak lulus ujian. Jika paspor hilang, silakan pergi ke polisi. Jika hujan, pertandingan dibatalkan.",
      "Jika akan terlambat, tolong hubungi. Jika tidak mengerti, tolong tanyakan kepada guru. Dalam keadaan darurat, tolong telepon nomor ini.",
      "Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan. Sambil mempertimbangkan alasannya, penulis membandingkan cara mana yang paling baik. Karena berbagi informasi dengan orang sekitar, penyebab masalah menjadi lebih mudah dipahami. Akhir-akhir ini penulis membiasakan diri memeriksa bukan hanya jadwal, tetapi juga alasannya.",
      "Penulis merasa sebaiknya mendengarkan pendapat orang sekitar ketika diperlukan. Pada pagi hari waktu pelajaran diperiksa. Di kelas, siswa membaca bahasa Jepang dan mendengarkan penjelasan guru. Kosakata yang belum dipahami ditulis di buku catatan. Saat istirahat, siswa membicarakan isi pelajaran bersama teman. Setelah pulang, isi pelajaran hari itu diperiksa sekali lagi.",
      "Ada rencana belajar berikutnya yang akan dilakukan. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya."
    ],
