    "translation": [
      "Saya pergi ke sekolah tanpa sarapan. Saya pergi keluar tanpa membawa payung. Saya akan mencoba makan masakan ini. Saya mencoba mencari kata yang tidak dimengerti di kamus.",
      "Setelah makan, barang yang diperlukan berikutnya diperiksa. Ada rencana berikutnya yang berkaitan dengan makanan atau belanja. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya.",
      "Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Penulis menjelaskan alasan dan tindakan dengan hubungan sebab-akibat. Penulis menjelaskan rencana untuk kegiatan berikutnya.",
      "Penulis menjelaskan kebiasaan yang sengaja dipertahankan. Menurut 山田, kabarnya akhir-akhir ini semakin banyak orang yang menggunakan cara ini. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Lain kali penulis juga ingin mencoba cara lain. Beberapa informasi diperiksa dari pagi hingga siang."
    ],
