    "translation": [
      "Saya akan mencoba makan masakan ini. Saya mencoba menggunakan cara baru. Saya pergi ke sekolah tanpa sarapan.",
      "Dia pulang tanpa mengatakan apa-apa. Saya mencoba mencari kata yang tidak dimengerti di kamus.",
      "Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Penulis menjelaskan alasan dan tindakan dengan hubungan sebab-akibat. Penulis menjelaskan rencana untuk kegiatan berikutnya.",
      "Penulis menjelaskan kebiasaan yang sengaja dipertahankan. Menurut 佐藤, kabarnya akhir-akhir ini semakin banyak orang yang menggunakan cara ini. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Lain kali penulis juga ingin mencoba cara lain. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan."
    ],
