    "translation": [
      "Kota ini mungkin akan terus berubah ke depan. Populasi mungkin akan terus berkurang mulai sekarang. Saya sedang mengerjakan PR sekarang.",
      "Saya sedang berbicara dengan guru. Mulai sekarang cuaca akan semakin panas.",
      "Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Penulis menjelaskan alasan dan tindakan dengan hubungan sebab-akibat. Penulis menjelaskan rencana untuk kegiatan berikutnya.",
      "Penulis menjelaskan kebiasaan yang sengaja dipertahankan. Menurut 鈴木, kabarnya akhir-akhir ini semakin banyak orang yang menggunakan cara ini. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Lain kali penulis juga ingin mencoba cara lain. Akhir-akhir ini penulis perlahan menjadi lebih mampu berpikir dengan tenang dibanding sebelumnya. Beberapa informasi diperiksa dari pagi hingga siang."
    ],
