    "translation": [
      "Belakangan pekerjaan mulai menjadi sibuk. Saya pergi membeli minuman sebentar lalu kembali. Saya sedang berbicara dengan guru.",
      "Kami baru akan memulai rapat. Saya dipuji oleh guru. Saya baru akan makan siang sekarang.",
      "Penulis menjelaskan alasan dan tindakan dengan hubungan sebab-akibat. Penulis menjelaskan rencana untuk kegiatan berikutnya. Penulis menjelaskan kebiasaan yang sengaja dipertahankan. Menurut ミラー, kabarnya akhir-akhir ini semakin banyak orang yang menggunakan cara ini. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Lain kali penulis juga ingin mencoba cara lain.",
      "Akhir-akhir ini penulis perlahan menjadi lebih mampu berpikir dengan tenang dibanding sebelumnya. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang.",
      "Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Walaupun rencana berubah, keadaan dapat ditangani jika hal yang diperlukan diperiksa. Memilih cara yang sesuai dengan situasi saat itu juga diperlukan."
    ],
